import csv
import io


def parse_csv(raw_csv: str):
    old_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2**31 - 1)
        reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
        records = list(reader)
    finally:
        csv.field_size_limit(old_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])
    existing = set(columns)
    index = 1
    while len(columns) < width:
        name = "extra_" + str(index)
        index += 1
        if name not in existing:
            columns.append(name)
            existing.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
